# 
# Generate 2D textures (EXR files) from particle text data for Unity VFX Graph sampling
#
# This file calls texturify_2d.create_texture_2d() with various parameters to convert 
# text files (generated by fry_*.py scripts) into ready-to-use 2D texture images

from loguru import logger
from astrocutlery.texturify_2d import create_texture_2d, prepend_zeros


# San Han galaxy cluster
def plate_maxime_lombart_amr(is_test=False):
	"""
	Generate 2D EXR textures from Maxime Lombart AMR particle text data.
	Requires text file generated by fry_mlombart_dustycollapse.py
	"""
	# Texture generation parameters
	# These define the min/max ranges used to normalize each data column
	# Columns: x, y, z, density, dx, rhogas, speak
	dimension_qualities = ["HQ", "HQ", "HQ", "HQ", "HQ", "HQ"]
	
	# File and path parameters
	source_author_folder = "maximelombart"
	source_frames_folder = "1-frame-amr"
	source_frame_index = 145
	source_file_name = "maximelombart-amr-" + prepend_zeros(source_frame_index, 4) + ("-testing" if is_test else "")
	output_base_dir = "./output"
	
	logger.info(f"[plate_maxime_lombart_amr] Starting texture generation for {source_file_name}")
	
	# Generate textures from text data
	create_texture_2d(source_author_folder, source_frames_folder, source_file_name, dimension_qualities, output_base_dir)
	
	logger.info(f"[plate_maxime_lombart_amr] Texture generation complete 👌")


if __name__ == "__main__":
	plate_maxime_lombart_amr()
